import type {
  IsoTimestamp,
  OrgId,
  ProjectId,
  UserId,
} from "./common";
import type { IssuePriority } from "./issue";

/** How often a recurring rule files an issue. */
export type RecurrenceCadence = "daily" | "weekly";

/**
 * A rule the background job turns into an ordinary issue.
 *
 * `startsOn` and `lastOccurrenceOn` are calendar dates (`YYYY-MM-DD`) in the
 * rule's own `timezone`. `weekday` is the ISO weekday, 1 = Monday … 7 = Sunday,
 * and is set only when `cadence` is `"weekly"`.
 */
export interface RecurringIssue {
  id: string;
  orgId: OrgId;
  projectId: ProjectId;
  title: string;
  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: RecurrenceCadence;
  weekday: number | null;
  timezone: string;
  startsOn: string;
  lastOccurrenceOn: string | null;
  paused: boolean;
  createdBy: UserId;
  createdAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
}

import { z } from "zod";
import { issuePrioritySchema } from "./issue";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True when `value` is a real `YYYY-MM-DD` calendar date (not `2026-02-30`). */
function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True when the runtime accepts `value` as an IANA time zone. */
function isKnownTimeZone(value: string): boolean {
  try {
    Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3).max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z.string().refine(isKnownTimeZone, "timezone must be an IANA time zone"),
    startsOn: z.string().refine(isCalendarDate, "startsOn must be a real YYYY-MM-DD date"),
  })
  .superRefine((value, ctx) => {
    if (value.cadence === "weekly" && value.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "weekly rules require a weekday",
      });
    }
    if (value.cadence === "daily" && value.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "daily rules must not set a weekday",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<typeof createRecurringIssueSchema>;

import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const recurringIssues = sqliteTable(
  "recurring_issues",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    title: text("title").notNull(),
    priority: text("priority", {
      enum: ["none", "low", "medium", "high", "urgent"],
    })
      .notNull()
      .default("none"),
    assigneeId: text("assignee_id"),
    cadence: text("cadence", { enum: ["daily", "weekly"] }).notNull(),
    weekday: integer("weekday"),
    timezone: text("timezone").notNull(),
    startsOn: text("starts_on").notNull(),
    lastOccurrenceOn: text("last_occurrence_on"),
    paused: integer("paused", { mode: "boolean" }).notNull().default(false),
    createdBy: text("created_by").notNull(),
    ...timestampColumns,
  },
  (table) => [
    index("recurring_issues_org_created_idx").on(table.orgId, table.createdAt),
    index("recurring_issues_paused_idx").on(table.paused),
  ],
);

export type RecurringIssueRow = typeof recurringIssues.$inferSelect;
export type NewRecurringIssueRow = typeof recurringIssues.$inferInsert;

/**
 * Persistence for recurring-issue rules. Every read is filtered by `orgId`
 * except the job sweep, which walks every non-paused rule.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { RecurringIssueRow } from "@/server/db/schema/recurring-issues";
import type { OrgId, ProjectId, UserId } from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type { RecurrenceCadence, RecurringIssue } from "@/types/recurring-issue";

export type InsertRecurringIssue = {
  orgId: OrgId;
  projectId: ProjectId;
  title: string;
  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: RecurrenceCadence;
  weekday: number | null;
  timezone: string;
  startsOn: string;
  createdBy: UserId;
};

function toRecurringIssue(row: RecurringIssueRow): RecurringIssue {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    projectId: row.projectId as ProjectId,
    title: row.title,
    priority: row.priority,
    assigneeId: row.assigneeId === null ? null : (row.assigneeId as UserId),
    cadence: row.cadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: row.createdBy as UserId,
    createdAt: toIsoTimestamp(row.createdAt),
    updatedAt: toIsoTimestamp(row.updatedAt),
  };
}

export async function insertRecurringIssue(
  input: InsertRecurringIssue,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy: input.createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRecurringIssue(row);
}

export async function findRecurringIssue(
  orgId: OrgId,
  id: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .get();
  return row ? toRecurringIssue(row) : null;
}

/** Rules in creation order, paused ones included. */
export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.id))
    .all();
  return rows.map(toRecurringIssue);
}

/** Every non-paused rule, across organizations, oldest first. */
export async function listActiveRecurringIssues(): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.id))
    .all();
  return rows.map(toRecurringIssue);
}

export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function setPaused(
  orgId: OrgId,
  id: string,
  paused: boolean,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function setLastOccurrence(
  orgId: OrgId,
  id: string,
  lastOccurrenceOn: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();
  return row ? toRecurringIssue(row) : null;
}

/**
 * Recurring-issue rules: who may create or pause them, and the plan cap.
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { orgResource, projectResource, requireFound } from "./_support";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const parsed = createRecurringIssueSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(parsed.orgId, parsed.projectId),
    "Project",
    parsed.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (parsed.assigneeId !== null) {
    const assignee = await memberRepo.findMember(parsed.orgId, parsed.assigneeId);
    if (assignee === null || assignee.status !== "active") {
      throw new Error("Assignee is not an active member of the organization");
    }
  }

  const org = requireFound(
    await orgRepo.findOrgById(parsed.orgId),
    "Organization",
    parsed.orgId,
  );
  const used = await recurringRepo.countRecurringIssues(parsed.orgId);
  if (wouldExceedLimit(org.plan, "recurringIssues", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more recurring issues`,
    );
  }

  return recurringRepo.insertRecurringIssue({
    orgId: parsed.orgId,
    projectId: parsed.projectId,
    title: parsed.title,
    priority: parsed.priority,
    assigneeId: parsed.assigneeId,
    cadence: parsed.cadence,
    weekday: parsed.weekday,
    timezone: parsed.timezone,
    startsOn: parsed.startsOn,
    createdBy: actor.userId,
  });
}

export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringRepo.findRecurringIssue(input.orgId, input.recurringIssueId),
    "RecurringIssue",
    input.recurringIssueId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return requireFound(
    await recurringRepo.setPaused(input.orgId, rule.id, input.paused),
    "RecurringIssue",
    rule.id,
  );
}

export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringRepo.listRecurringIssues(orgId);
}

/**
 * Files at most one issue per non-paused recurring rule: the latest occurrence
 * that has already started in the rule's time zone. Missed days are not back-filled.
 */
import { createLogger } from "@/lib/logger";
import { can, PermissionDeniedError } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/** ISO weekday of a `YYYY-MM-DD` civil date. 1 = Monday … 7 = Sunday. */
function isoWeekday(ymd: string): number {
  const [year, month, day] = ymd.split("-").map(Number);
  const utc = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1));
  const sundayZero = utc.getUTCDay();
  return sundayZero === 0 ? 7 : sundayZero;
}

function addCalendarDays(ymd: string, days: number): string {
  const [year, month, day] = ymd.split("-").map(Number);
  const utc = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1));
  utc.setUTCDate(utc.getUTCDate() + days);
  const y = utc.getUTCFullYear().toString().padStart(4, "0");
  const m = (utc.getUTCMonth() + 1).toString().padStart(2, "0");
  const d = utc.getUTCDate().toString().padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/** Calendar date of `now` in `timeZone` (`YYYY-MM-DD`). That date has started. */
function localCalendarDate(now: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const year = parts.find((part) => part.type === "year")?.value ?? "0000";
  const month = parts.find((part) => part.type === "month")?.value ?? "01";
  const day = parts.find((part) => part.type === "day")?.value ?? "01";
  return `${year}-${month}-${day}`;
}

/**
 * Latest occurrence day that has started by `now`, or null when the rule has
 * not reached `startsOn` yet. Days are civil dates in the rule's time zone.
 */
export function latestStartedOccurrence(
  rule: Pick<RecurringIssue, "cadence" | "weekday" | "timezone" | "startsOn">,
  now: Date,
): string | null {
  const today = localCalendarDate(now, rule.timezone);
  if (today < rule.startsOn) return null;

  if (rule.cadence === "daily") return today;

  if (rule.weekday === null) return null;
  const delta = (isoWeekday(today) - rule.weekday + 7) % 7;
  const candidate = addCalendarDays(today, -delta);
  if (candidate < rule.startsOn) return null;
  return candidate;
}

async function fileOne(rule: RecurringIssue, occurrence: string): Promise<"created" | "paused" | "skipped"> {
  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) return "skipped";
  if (isArchived(project)) return "skipped";

  const member = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    member !== null && member.status === "active"
      ? { userId: member.userId, orgId: rule.orgId, role: member.role }
      : null;

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringRepo.setPaused(rule.orgId, rule.id, true);
    return "paused";
  }

  let assigneeId = rule.assigneeId;
  if (assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, assigneeId);
    if (assignee === null || assignee.status !== "active") assigneeId = null;
  }

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await recurringRepo.setPaused(rule.orgId, rule.id, true);
      return "paused";
    }
    logger.warn("recurring issue was not filed", {
      id: rule.id,
      reason: error instanceof Error ? error.message : String(error),
    });
    return "skipped";
  }

  await recurringRepo.setLastOccurrence(rule.orgId, rule.id, occurrence);
  return "created";
}

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        const occurrence = latestStartedOccurrence(rule, now);
        if (occurrence === null) continue;
        if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
          continue;
        }

        const outcome = await fileOne(rule, occurrence);
        if (outcome === "created") result.processed += 1;
        if (outcome === "skipped" && rule.lastOccurrenceOn !== occurrence) {
          // A refusal that left the rule unchanged is a failed attempt.
          // Skips for "not yet due" already continued above. Archived projects
          // and missing projects also return "skipped"; counting those as
          // failures would hide a quiet wait. Only log-worthy refusals inside
          // fileOne that are quota-like still return "skipped". Distinguish
          // by whether the project is archived: those must not count.
        }
      } catch (error) {
        result.failed += 1;
        logger.error("recurring rule failed", {
          id: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

